+#ifdef CONFIG_PATCH_HUMAX_NETWORKS
+int append_humax_configuration_tlv(unsigned char *pkt, struct p1905_managerd_ctx *ctx, int is_limit_hops)
+{
+	unsigned char *tlv_temp_buf = pkt;
+	unsigned char mtk_oui[3] = {0x00, 0x0C, 0xE7};
+	unsigned short total_tlvs_length = 0;
+
+	if ((ctx == NULL) || (pkt == NULL)) {
+		debug(DEBUG_ERROR, "Invalid input\n");
+		return 0;
+	}
+	/*1905 internal using vendor specific tlv format
+		type			1 byte			0x11
+		length			2 bytes			0x, 0x
+		oui			3 bytes			0x00, 0x0C, 0xE7
+		function type	1 byte			0xff
+		suboui			3 bytes			0x00, 0x0C, 0xE7
+		sub func type	1 byte			0x
+		teardown retry	2 byte
+		max hop limit	1 byte			0x00 or 0x01
+	*/
+
+	/*vendor specific tlv type*/
+	*tlv_temp_buf++ = VENDOR_SPECIFIC_TLV_TYPE;
+
+	/*vendor specific tlv length*/
+	tlv_temp_buf += 2;
+
+	/*oui*/
+	os_memcpy(tlv_temp_buf, mtk_oui, sizeof(mtk_oui));
+	tlv_temp_buf += sizeof(mtk_oui);
+
+	/*function type*/
+	*tlv_temp_buf++ = 0xff;
+
+	/*additional OUI*/
+	os_memcpy(tlv_temp_buf, mtk_oui, sizeof(mtk_oui));
+	tlv_temp_buf += sizeof(mtk_oui);
+
+	/*1905 internal used vendor specific subtype*/
+	*tlv_temp_buf++ = internal_humax_configuration_message_subtype;
+
+	/*time teardown retry ap autpconfig*/
+	*((unsigned short*)(tlv_temp_buf)) = host_to_be16(ctx->time_teardown_retry_autoconfig);
+	tlv_temp_buf += 2;
+
+	/* Add max limit number of wifi config */
+	if (is_limit_hops) {
+		*tlv_temp_buf = OVER_DO_LIMIT;
+		tlv_temp_buf += 1;
+	} else {
+		*tlv_temp_buf = NOT_OVER_LIMIT;
+		tlv_temp_buf += 1;
+	}
+
+	total_tlvs_length = (unsigned short)(tlv_temp_buf - pkt);
+
+	/*Set vendor specific tlv length*/
+	*((unsigned short*)(pkt + 1)) = host_to_be16(total_tlvs_length - 3); 	/*tlv type size = 1, tlv length size = 2*/
+
+	return total_tlvs_length;
+}
+
+int check_p1905_dev_num(struct p1905_managerd_ctx *ctx, unsigned char *al_mac)
+{
+	int cur1905DevNum = 0;
+	int alIdx = 0;
+	struct topology_device_db *tpdev_db = NULL;
+
+	if ((ctx == NULL) || (al_mac == NULL)) {
+		debug(DEBUG_ERROR, "Invalid input\n");
+		return NOT_OVER_LIMIT;
+	}
+
+	if(ctx->max_hop <= 0) {
+		debug(DEBUG_ERROR, "Do no limit\n");
+		return NOT_OVER_LIMIT;
+	}
+
+	if (!SLIST_EMPTY(&ctx->topodev_entry.tpdevdb_head)) {
+		SLIST_FOREACH(tpdev_db, &ctx->topodev_entry.tpdevdb_head, tpdev_entry) {
+			/*Count all p1905dev except self*/
+			cur1905DevNum++;
+			debug(DEBUG_OFF, "[idx = %d] tpdev_db->aldev_mac="MACSTR"\n",
+						cur1905DevNum, PRINT_MAC(tpdev_db->aldev_mac));
+
+			if (!os_memcmp(tpdev_db->aldev_mac, al_mac, ETH_ALEN)) {
+				alIdx = cur1905DevNum;
+			}
+		}
+
+		debug(DEBUG_OFF, "alIdx = %d \n", alIdx);
+		/*Revert index*/
+		alIdx = cur1905DevNum - alIdx + 1;
+		debug(DEBUG_OFF, "revert alIdx = %d\n", alIdx);
+
+		if (alIdx > (ctx->max_hop - 1)) {
+			debug(DEBUG_OFF, "OVER_DO_LIMIT\n");
+			return OVER_DO_LIMIT;
+		}
+	}
+
+	debug(DEBUG_OFF, "NOT_OVER_LIMIT\n");
+
+	return NOT_OVER_LIMIT;
+}
+
+void ap_set_backhaul_sta(char* action)
+{
+	int port = 1;
+	char cmd[128] = {0};
+
+	if (action == NULL) {
+		debug(DEBUG_ERROR, "Invalid input\n");
+		return;
+	}
+
+	debug(DEBUG_OFF, "%s ALL Backhaul STA interface!!!\n", action);
+
+	/*Backhaul interface*/
+	snprintf(cmd, sizeof(cmd), "/sbin/ifconfig apclii0 %s", action);
+	system(cmd);
+	usleep(500000);
+
+	for (port = 1; port <= MAX_ETH_PORT; port++) {
+		snprintf(cmd, sizeof(cmd), "/sbin/ifconfig eth0.%d %s", port, action);
+		system(cmd);
+		usleep(500000);
+	}
+}
+
+void ap_recover_backhaul_sta(void *eloop_data, void *user_ctx) {
+	struct p1905_managerd_ctx *ctx = (struct p1905_managerd_ctx*)eloop_data;
+
+	if (ctx == NULL) {
+		debug(DEBUG_ERROR, "Invalid input\n");
+		return;
+	}
+
+	debug(DEBUG_OFF, "Recover Backhaul Sta for mesh pairing\n");
+	ap_set_backhaul_sta("up");
+	_1905_trigger_ap_selection_scan(ctx);
+}
