+#ifdef CONFIG_PATCH_HUMAX_NETWORKS
+static int topo_srv_get_bh_wireless_rate_via_neighbor_device(struct _1905_map_device *neighbor_dev,
+                                                            const unsigned char *connected_iface_mac,
+                                                            unsigned int *out_bh_rate_max_mbps,
+                                                            unsigned int *out_uplink_mbps,
+                                                            unsigned int *out_downlink_mbps,
+                                                            unsigned int *out_max_phyrate_mbps)
+
+{
+    struct associated_clients *client = NULL, *tclient = NULL;
+
+    if (out_bh_rate_max_mbps != NULL)
+    {
+        *out_bh_rate_max_mbps = 0;
+    }
+    if (out_uplink_mbps != NULL)
+    {
+        *out_uplink_mbps = 0;
+    }
+    if (out_downlink_mbps != NULL)
+    {
+        *out_downlink_mbps = 0;
+    }
+    if (out_max_phyrate_mbps != NULL)
+    {
+        *out_max_phyrate_mbps = 0;
+    }
+
+    if ((neighbor_dev == NULL) || (connected_iface_mac == NULL) || (out_bh_rate_max_mbps == NULL))
+    {
+        return -1;
+    }
+
+/* On neighbor side, the connected iface MAC is typically visible as an associated STA MAC. */
+    SLIST_FOREACH_SAFE(client, &neighbor_dev->assoc_clients, next_client, tclient)
+    {
+        if (os_memcmp(client->client_addr, connected_iface_mac, ETH_ALEN) == 0)
+        {
+            unsigned int up = client->erate_uplink;
+            unsigned int down = client->erate_downlink;
+            unsigned int max_phy = client->max_phyrate;
+
+            if (out_uplink_mbps != NULL)
+            {
+                *out_uplink_mbps = up;
+            }
+            if (out_downlink_mbps != NULL)
+            {
+                *out_downlink_mbps = down;
+            }
+            if (out_max_phyrate_mbps != NULL)
+            {
+                *out_max_phyrate_mbps = max_phy;
+            }
+
+            /* Prefer valid max_phyrate; otherwise use max(uplink_rate, dnlink_rate). */
+            if ((max_phy > 0) && (max_phy != 65535))
+            {
+                *out_bh_rate_max_mbps = max_phy;
+            }
+            else
+            {
+                *out_bh_rate_max_mbps = (up >= down) ? up : down;
+            }
+            return 0;
+        }
+    }
+
+    return -1;
+}
+
+
