+VOID sort_bss_entry_by_channel(BSS_TABLE *arr, INT n)
+{
+	INT i = 0, j = 0;
+	BSS_ENTRY *tempBssEntry = NULL;
+
+	os_alloc_mem(NULL, (UCHAR **)&tempBssEntry, sizeof(BSS_ENTRY));
+
+	if ((arr == NULL) || (tempBssEntry == NULL)) {
+		return;
+	}
+
+	for (i = 0; i < n - 1; i++) {
+		for (j = 0; j < n - i - 1; j++) {
+			if (arr->BssEntry[j].Channel > arr->BssEntry[j + 1].Channel) {
+				*tempBssEntry = arr->BssEntry[j];
+				arr->BssEntry[j] = arr->BssEntry[j + 1];
+				arr->BssEntry[j + 1] = *tempBssEntry;
+			}
+		}
+	}
+
+	os_free_mem(tempBssEntry);
+	return;
+}
+
+INT rearrage_bss_entry_struct(BSS_TABLE *arr, INT n, INT pos)
+{
+	INT i = 0;
+
+	if (arr == NULL) {
+		return 0;
+	}
+
+	if (n <= 0) {
+		return 0;
+	}
+	if (pos < 0) {
+		pos = 0;
+	} else if (pos >= n) {
+		pos = n-1;
+	}
+
+	for (i = pos; i < n - 1; i++) {
+		/* Shift the elements to the left to fill the deleted element's position */
+		arr->BssEntry[i] = arr->BssEntry[i+1];
+	}
+	--n;
+	return n;
+}
