+        /* Entry type filter */
+        if (ent_type == ENTRY_NONE) {
+            if (pEntry->EntryType == ENTRY_NONE)
+                continue;
+        } else {
+            if (pEntry->EntryType != ent_type)
+                continue;
+
+            if ((IS_ENTRY_CLIENT(pEntry) || IS_ENTRY_PEER_AP(pEntry) || IS_ENTRY_REPEATER(pEntry)) &&
+                (pEntry->Sst != SST_ASSOC))
+                continue;
+
+#ifdef MAC_REPEATER_SUPPORT
+            if (bReptCli == FALSE) {
+                /* Only dump apcli entry which is NOT a RepeaterCli */
+                if (IS_REPT_LINK_UP(pEntry->pReptCli))
+                    continue;
+            }
+#endif /* MAC_REPEATER_SUPPORT */
+        }
+
+        /* Count info */
+        if (IS_ENTRY_CLIENT(pEntry)) {
+            pwdev = pEntry->wdev;
+            if (pwdev)
+                band_idx = HcGetBandByWdev(pwdev);
+            sta_cnt++;
+            if (band_idx < MAX_BAND_NUM)
+                sta_cnt_band[band_idx]++;
+        }
+
+        if (IS_ENTRY_PEER_AP(pEntry))
+            apcli_cnt++;
+
+        /* ----------------------------- */
+        /* MAC, MIMOPS */
+        /* ----------------------------- */
+        HMX_PRINT(pos, end, MACSTR, MAC2STR(pEntry->Addr));
+        HMX_PRINT(pos, end, "\t");
+
+#ifdef DOT11_N_SUPPORT
+        HMX_PRINT(pos, end, "%d\t", (int)pEntry->MmpsMode);
+#else
+        HMX_PRINT(pos, end, "0\t");
+#endif
+
+        /* ----------------------------- */
+        /* RSSI0/1/2/3 */
+        /* ----------------------------- */
+        for (j = 0; j < ARRAY_SIZE(rssi); j++)
+            rssi[j] = -127;
+
+        if (pEntry->wdev && pEntry->wdev->sys_handle) {
+            ad = pEntry->wdev->sys_handle;
+            rssi_len = MCS_NSS_CAP(ad)->max_path[MAX_PATH_RX];
+        } else {
+            ad = NULL;
+            rssi_len = 0;
+        }
+
+        rtmp_get_rssi(pAd, pEntry->wcid, rssi, rssi_len);
+
+        ret = 0;
+        tmp_str[0] = '\0';
+        for (j = 0; j < 4; j++) {
+            left_buf_size = temp_str_len - ret;
+            if (left_buf_size <= 0)
+                break;
+
+            if (j < rssi_len)
+                ret += snprintf((char *)tmp_str + ret, left_buf_size, "%d", rssi[j]);
+            else
+                ret += snprintf((char *)tmp_str + ret, left_buf_size, "--");
+
+            if (j < 3) {
+                left_buf_size = temp_str_len - ret;
+                if (left_buf_size <= 0)
+                    break;
+                ret += snprintf((char *)tmp_str + ret, left_buf_size, "/");
+            }
+
+            if (os_snprintf_error((size_t)temp_str_len, ret))
+                break;
+        }
+        HMX_PRINT(pos, end, "%s\t", tmp_str);
+
+        /* ----------------------------- */
+        /* SNR0/1/2/3 */
+        /* ----------------------------- */
+        os_zero_mem(u1Snr, sizeof(u1Snr));
+        UniCmdPerStaGetSNR(pAd, pEntry->wcid, u1Snr);
+
+        ret = 0;
+        tmp_str[0] = '\0';
+        for (j = 0; j < 4; j++) {
+            left_buf_size = temp_str_len - ret;
+            if (left_buf_size <= 0)
+                break;
+
+            if (j < rssi_len)
+                ret += snprintf((char *)tmp_str + ret, left_buf_size, "%d", u1Snr[j]);
+            else
+                ret += snprintf((char *)tmp_str + ret, left_buf_size, "--");
+
+            if (j < 3) {
+                left_buf_size = temp_str_len - ret;
+                if (left_buf_size <= 0)
+                    break;
+                ret += snprintf((char *)tmp_str + ret, left_buf_size, "/");
+            }
+
+            if (os_snprintf_error((size_t)temp_str_len, ret))
+                break;
+        }
+        HMX_PRINT(pos, end, "%s\t", tmp_str);
+
+        /* ----------------------------- */
+        /* BW(T/R), MCS(T/R), SGI(T/R), linkrate(tx/rx) */
+        /*   - Try to use FW offload info when available */
+        /*   - Otherwise use HTPhyMode for Tx and "NA" for Rx& */
+        /* ----------------------------- */
+#ifdef RACTRL_FW_OFFLOAD_SUPPORT
+        if (cap && (cap->fgRateAdaptFWOffload == TRUE)) {
+            UCHAR phy_mode = 0, rate = 0, bw = 0, sgi = 0, stbc = 0;
+            UCHAR phy_mode_r = 0, rate_r = 0, bw_r = 0, sgi_r = 0, stbc_r = 0;
+            UCHAR nss = 0, nss_r = 0;
+            UINT32 RawData = 0;
+            UINT32 lastTxRate = 0;
+            UINT32 lastRxRate = pEntry->LastRxRate;
+            UCHAR ucBand = 0;
+
+            EXT_EVENT_TX_STATISTIC_RESULT_T rTxStatResult;
+            EXT_EVENT_PHY_STATE_RX_RATE rRxStatResult;
+            union _HTTRANSMIT_SETTING LastTxRate;
+            union _HTTRANSMIT_SETTING LastRxRate;
+
+            NdisZeroMemory(&rRxStatResult, sizeof(rRxStatResult));
+            NdisZeroMemory(&rTxStatResult, sizeof(rTxStatResult));
+
+            if (pEntry->wdev)
+                ucBand = HcGetBandByWdev(pEntry->wdev);
+
+            /* TX rate */
+            MtCmdGetTxStatistic(pAd, GET_TX_STAT_ENTRY_TX_RATE, 0 /* Don't Care */, pEntry->wcid, &rTxStatResult);
+            LastTxRate.field.MODE = rTxStatResult.rEntryTxRate.MODE;
+            LastTxRate.field.BW = rTxStatResult.rEntryTxRate.BW;
+            LastTxRate.field.ldpc = rTxStatResult.rEntryTxRate.ldpc ? 1 : 0;
+            LastTxRate.field.ShortGI = rTxStatResult.rEntryTxRate.ShortGI ? 1 : 0;
+            LastTxRate.field.STBC = rTxStatResult.rEntryTxRate.STBC;
+
+            if (LastTxRate.field.MODE >= MODE_VHT)
+                LastTxRate.field.MCS = (((rTxStatResult.rEntryTxRate.VhtNss - 1) & 0x3) << 4) +
+                                       rTxStatResult.rEntryTxRate.MCS;
+            else if (LastTxRate.field.MODE == MODE_OFDM)
+                LastTxRate.field.MCS = getLegacyOFDMMCSIndex(rTxStatResult.rEntryTxRate.MCS) & 0x0000003F;
+            else
+                LastTxRate.field.MCS = rTxStatResult.rEntryTxRate.MCS;
+
+            lastTxRate = (UINT32)(LastTxRate.word);
+            LastRxRate.word = (USHORT)lastRxRate;
+
+            RawData = lastTxRate;
+            phy_mode = rTxStatResult.rEntryTxRate.MODE;
+            rate = RawData & 0x3F;
+            bw = (RawData >> 7) & 0x7;
+            sgi = rTxStatResult.rEntryTxRate.ShortGI;
+            nss = rTxStatResult.rEntryTxRate.VhtNss;
+            stbc = ((RawData >> 10) & 0x1);
+
+            /* RX rate */
+            if (Get_Connected_Sta_RxRate(pAd, MaxConnectedNum, pEntry->wcid, &rRxStatResult) != TRUE)
+                MtCmdPhyGetRxRate(pAd, CMD_PHY_STATE_CONTENTION_RX_PHYRATE, ucBand, pEntry->wcid,
+                                  (UINT32 *)&rRxStatResult);
+
+            phy_mode_r = rRxStatResult.u1RxMode;
+            rate_r = rRxStatResult.u1RxRate & 0x3F;
+            bw_r = rRxStatResult.u1BW;
+            sgi_r = rRxStatResult.u1Gi;
+            stbc_r = rRxStatResult.u1Stbc;
+
+            /* BW(T/R) */
+            HMX_PRINT(pos, end, "%s/%s\t",
+                      get_bw_str_stainfo(bw, BW_FROM_TXRX_INFO),
+                      get_bw_str_stainfo(bw_r, BW_FROM_TXRX_INFO));
+
+            /* MCS(T/R) */
+            tmp_str[0] = '\0';
+#ifdef DOT11_VHT_AC
+            if (phy_mode >= MODE_VHT) {
+                UCHAR tx_mcs = (rate & 0xF);
+                snprintf((char *)tmp_str, temp_str_len, "%dS-M%d/", nss, tx_mcs);
+            } else
+#endif
+            {
+                snprintf((char *)tmp_str, temp_str_len, "%d/", rate);
+            }
+
+            if (phy_mode_r == MODE_UNKNOWN) {
+                left_buf_size = temp_str_len - (INT)strlen((char *)tmp_str);
+                if (left_buf_size > 0)
+                    snprintf((char *)tmp_str + strlen((char *)tmp_str), left_buf_size, "NA");
+            } else {
+#ifdef DOT11_VHT_AC
+                if (phy_mode_r >= MODE_VHT) {
+                    nss_r = (rRxStatResult.u1RxNsts + 1) / (rRxStatResult.u1Stbc + 1);
+                    rate_r = rate_r & 0xF;
+                    left_buf_size = temp_str_len - (INT)strlen((char *)tmp_str);
+                    if (left_buf_size > 0)
+                        snprintf((char *)tmp_str + strlen((char *)tmp_str), left_buf_size, "%dS-M%d", nss_r, rate_r);
+                } else
+#endif
+#if DOT11_N_SUPPORT
+                if (phy_mode_r >= MODE_HTMIX) {
+                    left_buf_size = temp_str_len - (INT)strlen((char *)tmp_str);
+                    if (left_buf_size > 0)
+                        snprintf((char *)tmp_str + strlen((char *)tmp_str), left_buf_size, "%d", rate_r);
+                } else
+#endif
+                {
+                    left_buf_size = temp_str_len - (INT)strlen((char *)tmp_str);
+                    if (left_buf_size > 0)
+                        snprintf((char *)tmp_str + strlen((char *)tmp_str), left_buf_size, "%d", rate_r);
+                }
+            }
+            HMX_PRINT(pos, end, "%s\t", tmp_str);
+
+            /* SGI(T/R) */
+            HMX_PRINT(pos, end, "%s/%s\t",
+                      get_gi_str(phy_mode, sgi),
+                      (phy_mode_r == MODE_UNKNOWN) ? "NA" : get_gi_str(phy_mode_r, sgi_r));
+
+            /* linkrate(T/R): DataRate/DataRate_r */
+            if (phy_mode >= MODE_HE) {
+#ifdef DOT11_EHT_BE
+                if ((phy_mode == MODE_EHT) || (phy_mode == MODE_EHT_ER_SU) || (phy_mode == MODE_EHT_TB) || (phy_mode == MODE_EHT_MU))
+                    get_rate_eht((rate & 0xF), bw, nss, 0, &DataRate);
+                else
+#endif
+                    get_rate_he((rate & 0xF), bw, nss, 0, &DataRate);
+
+                if (sgi == 1) DataRate = (DataRate * 967) >> 10;
+                if (sgi == 2) DataRate = (DataRate * 870) >> 10;
+            } else {
+                getRate(LastTxRate, &DataRate);
+            }
+
+            if (phy_mode_r >= MODE_HE && phy_mode_r < MODE_UNKNOWN) {
+#ifdef DOT11_EHT_BE
+                if ((phy_mode_r == MODE_EHT) || (phy_mode_r == MODE_EHT_ER_SU) || (phy_mode_r == MODE_EHT_TB) || (phy_mode_r == MODE_EHT_MU))
+                    get_rate_eht((rate_r & 0xF), bw_r, nss_r, 0, &DataRate_r);
+                else
+#endif
+                    get_rate_he((rate_r & 0xF), bw_r, nss_r, 0, &DataRate_r);
+
+                if (sgi_r == 1) DataRate_r = (DataRate_r * 967) >> 10;
+                if (sgi_r == 2) DataRate_r = (DataRate_r * 870) >> 10;
+            } else {
+                /* If rx mode is unknown, keep rx rate as 0 */
+                if (phy_mode_r != MODE_UNKNOWN) {
+                    LastRxRate.field.MODE = phy_mode_r;
+                    LastRxRate.field.BW = bw_r;
+                    LastRxRate.field.ShortGI = sgi_r ? 1 : 0;
+                    LastRxRate.field.STBC = stbc_r;
+                    getRate(LastRxRate, &DataRate_r);
+                }
+            }
+        } else
+#endif /* RACTRL_FW_OFFLOAD_SUPPORT */
+        {
+            /* Fallback: Tx only from HTPhyMode, Rx is NA (rate_r=0) */
+            HMX_PRINT(pos, end, "%s/NA\t",
+                      get_bw_str(pEntry->HTPhyMode.field.BW, BW_FROM_OID));
+
+#ifdef DOT11_VHT_AC
+            if (pEntry->HTPhyMode.field.MODE >= MODE_VHT) {
+                snprintf((char *)tmp_str, temp_str_len, "%dS-M%d/NA",
+                         ((pEntry->HTPhyMode.field.MCS >> 4) + 1),
+                         (pEntry->HTPhyMode.field.MCS & 0xf));
+            } else
+#endif
+            {
+                snprintf((char *)tmp_str, temp_str_len, "%d/NA", pEntry->HTPhyMode.field.MCS);
+            }
+            HMX_PRINT(pos, end, "%s\t", tmp_str);
+
+            HMX_PRINT(pos, end, "%d/NA\t", pEntry->HTPhyMode.field.ShortGI);
+
+            /* linkrate(T/R): use Tx only, Rx=0 */
+            getRate(pEntry->HTPhyMode, &DataRate);
+            DataRate_r = 0;
+        }
+
+
+        /* ----------------------------- */
+        /* MaxBW, MaxMCS, MaxLinkRate */
+        /* ----------------------------- */
+        PhyMode = pEntry->MaxHTPhyMode;
+
+        /* MaxBW */
+        HMX_PRINT(pos, end, "%s\t", get_bw_str(PhyMode.field.BW, BW_FROM_OID));
+
+        /* MaxMCS (string) */
+        tmp_str[0] = '\0';
+
+#ifdef DOT11_VHT_AC
+        if (PhyMode.field.MODE >= MODE_VHT) {
+            snprintf((char *)tmp_str, temp_str_len, "%dS-M%d",
+                     ((PhyMode.field.MCS >> 4) + 1),
+                     (PhyMode.field.MCS & 0xf));
+        } else
+#endif
+        {
+            snprintf((char *)tmp_str, temp_str_len, "%d", PhyMode.field.MCS);
+        }
+
+        /* MaxLinkRate: max_DataRate */
+        if (PhyMode.field.MODE >= MODE_HE) {
+#ifdef DOT11_EHT_BE
+            if (PhyMode.field.MODE == MODE_EHT)
+                get_rate_eht((PhyMode.field.MCS & 0xF),
+                             PhyMode.field.BW,
+                             ((PhyMode.field.MCS >> 4) & 0x3) + 1,
+                             0, &max_DataRate);
+            else
+#endif
+                get_rate_he((PhyMode.field.MCS & 0xF),
+                            PhyMode.field.BW,
+                            ((PhyMode.field.MCS >> 4) & 0x3) + 1,
+                            0, &max_DataRate);
+        } else {
+            getRate(PhyMode, &max_DataRate);
+        }
+
+        /* Print MaxMCS */
+        HMX_PRINT(pos, end, "%s\t", tmp_str);
+
+        /* ----------------------------- */
+        /* Time */
+        /* ----------------------------- */
+        HMX_PRINT(pos, end, "%04d:%02d:%02d\t",
+                  pEntry->StaConnectTime/3600,
+                  (pEntry->StaConnectTime/60)%60,
+                  pEntry->StaConnectTime%60);
+
+
+        /* ----------------------------- */
+        /* linkrate, maxlinkrate */
+        /* ----------------------------- */
+        HMX_PRINT(pos, end, "%lu/%lu\t%lu\n",
+                  (ULONG)DataRate,
+                  (ULONG)DataRate_r,
+                  (ULONG)max_DataRate);
+
+    }
+
+
+    return TRUE;
+}
