+
+        return FALSE;
+    }
+
+    pos = (char *)arg;
+    end = arg + HMX_MTK_NL80211_VENDOR_SUBCMD_VENDOR_SHOW_BUFFER_SIZE;
+    arg[0] = '\0';
+
+
+    return hmx_dump_mac_table(pAd, ent_type, FALSE, pos, end);
+}
