+static inline bool hmx_log_to_buffer(char **ppos, char *end, const char *fmt, ...)
+{
+    int ret;
+    size_t left;
+    va_list ap;
+
+    if (!ppos || !*ppos || !end || !fmt)
+        return false;
+
+    if (end <= *ppos)
+        return false;
+
+    left = (size_t)(end - *ppos);
+
+    va_start(ap, fmt);
+    ret = vsnprintf(*ppos, left, fmt, ap);
+    va_end(ap);
+
+    if (os_snprintf_error(left, ret))
+        return false;
+
+    *ppos += ret;
+    return true;
+}
+
+#define HMX_PRINT(pos, end, fmt, ...)                                  \
+    do {                                                               \
+        if (!hmx_log_to_buffer(&(pos), (end), (fmt), ##__VA_ARGS__))        \
+            return FALSE;                                              \
+    } while (0)
+
