+#ifdef CONFIG_HUMAX_NETWORKS_BH_FIX
+	/* Humax Networks: capture context before IE decisions */
+	if (bss[NL80211_BSS_BSSID]) {
+		hnx_bssid = nla_data(bss[NL80211_BSS_BSSID]);
+	}
+	if (bss[NL80211_BSS_FREQUENCY]) {
+		hnx_freq = (int)nla_get_u32(bss[NL80211_BSS_FREQUENCY]);
+		ieee80211_freq_to_chan((unsigned int)hnx_freq, (u8 *)&hnx_chan);
+	}
+	if (bss[NL80211_BSS_SIGNAL_MBM]) {
+		hnx_signal_mbm = (int)nla_get_u32(bss[NL80211_BSS_SIGNAL_MBM]);
+		hnx_has_signal = 1;
+	}
+	hnx_has_ie = bss[NL80211_BSS_INFORMATION_ELEMENTS] ? 1 : 0;
+
+	if (bss[NL80211_BSS_INFORMATION_ELEMENTS]) {
+		ie = nla_data(bss[NL80211_BSS_INFORMATION_ELEMENTS]);
+		ie_len = nla_len(bss[NL80211_BSS_INFORMATION_ELEMENTS]);
+	} else {
+		err(DEBUG_CAT_NL80211, "No Probe IE\n");
+	}
+
+	if (bss[NL80211_BSS_BEACON_IES]) {
+		beacon_ie = nla_data(bss[NL80211_BSS_BEACON_IES]);
+		beacon_ie_len = nla_len(bss[NL80211_BSS_BEACON_IES]);
+	} else {
+		/* Required: print context right before handling No beacon IE */
+		if (hnx_bssid) {
+			notice(DEBUG_CAT_NL80211,
+				"HNX_BH_FIX: No beacon IE ctx: bssid("MACSTR") freq(%d) chan(%d) signal_mbm(%s%d) ie_present(%d)\n",
+				MAC2STR(hnx_bssid),
+				hnx_freq,
+				(hnx_freq > 0) ? (int)hnx_chan : -1,
+				hnx_has_signal ? "" : "NA/",
+				hnx_has_signal ? hnx_signal_mbm : 0,
+				hnx_has_ie);
+		} else {
+			notice(DEBUG_CAT_NL80211,
+				"HNX_BH_FIX: No beacon IE ctx: bssid(NA) freq(%d) chan(%d) signal_mbm(%s%d) ie_present(%d)\n",
+				hnx_freq,
+				(hnx_freq > 0) ? (int)hnx_chan : -1,
+				hnx_has_signal ? "" : "NA/",
