+		beacon_ie = ie;
+		beacon_ie_len = ie_len;
+	}
+
+	if (!ie) {
+		notice(DEBUG_CAT_NL80211, "HNX_BH_FIX: fallback probe_ie <- beacon_ie\n");
+		ie = beacon_ie;
+		ie_len = beacon_ie_len;
+	}
+#else
 	if (bss[NL80211_BSS_INFORMATION_ELEMENTS]) {
 		ie = nla_data(bss[NL80211_BSS_INFORMATION_ELEMENTS]);
