diff --git a/airoha_feeds/target/linux/airoha/files/drivers/gpio/sgpio-airoha.c b/airoha_feeds/target/linux/airoha/files/drivers/gpio/sgpio-airoha.c
new file mode 100755
index 00000000000..a18eaf184ea
--- /dev/null
+++ b/airoha_feeds/target/linux/airoha/files/drivers/gpio/sgpio-airoha.c
@@ -0,0 +1,266 @@
+// SPDX-License-Identifier: GPL-2.0-only
+// Copyright (c) 2021-2023 Airoha Inc.
+/*
+ * SGPIO implementation based on Airoha SDK
+ *
+ * Author: Neha Rani  <neha.rani@airoha.com>
+ *
+ */
+
+#include <linux/types.h>
+#include <linux/io.h>
+#include <linux/bits.h>
+#include <linux/gpio.h>
+#include <linux/gpio/driver.h>
+#include <linux/mod_devicetable.h>
+#include <linux/module.h>
+#include <linux/platform_device.h>
+#include <linux/property.h>
+
+
+#define AIROHA_SGPIO_MAX 17
+#define SGPIODATA_OFFSET 0x00
+#define SGPIOCLK_OFFSET 0x04
+#define SGPIOCLDLY_OFFSET 0x08
+#define SERIAL_GPIO_CFG_OFFSET 0x0C
+#define SGPIO_ENABLE_REG_OFFSET 0x1fa2021c
+
+#define SGPIO_ENABLE_BIT 2
+#define SGPIO_RCLK_ENABLE_BIT 11
+struct airoha_sgpio {
+    struct gpio_chip chip;
+    void __iomem *base;
+    spinlock_t lock;
+    uint32_t mode;
+    uint32_t clk_div;
+    uint32_t clk_delay;
+};
+
+static void __iomem *sgpio_reg(struct airoha_sgpio *gpio, uint32_t offset)
+{
+    return gpio->base + offset;
+}
+
+static int airoha_sgpio_wait_for_shift(struct airoha_sgpio *gpio)
+{
+    uint32_t reg_val;
+    void __iomem *addr = sgpio_reg(gpio, SGPIODATA_OFFSET);
+    reg_val = ioread32(addr);
+	//pr_info("Reading data to SGPIODATA: 0x%x\n", reg_val);
+    while (reg_val & BIT(31)) {
+        reg_val = ioread32(addr);
+    }
+    return 0;
+}
+
+static void airoha_sgpio_write_data(struct airoha_sgpio *gpio, uint32_t data)
+{
+    void __iomem *addr = sgpio_reg(gpio, SGPIODATA_OFFSET);
+    airoha_sgpio_wait_for_shift(gpio);
+    //pr_info("Writing data to SGPIODATA: 0x%x\n", data);
+    iowrite32(data, addr);
+
+}
+
+static void airoha_sgpio_set_mode(struct airoha_sgpio *gpio, uint32_t mode)
+{
+    uint32_t reg_val;
+    void __iomem *addr = sgpio_reg(gpio, SERIAL_GPIO_CFG_OFFSET);
+
+    reg_val = ioread32(addr);
+	pr_info("Reading mode in SERIAL_GPIO_CFG: 0x%x\n", reg_val);
+    reg_val &= ~BIT(0); // Clear mode bit
+    reg_val |= mode;
+    pr_info("Setting mode in SERIAL_GPIO_CFG: 0x%x\n", reg_val);
+    iowrite32(reg_val, addr);
+}
+
+static void airoha_sgpio_enable(struct airoha_sgpio *gpio)
+{
+    uint32_t reg_val;
+    void __iomem *addr = ioremap(SGPIO_ENABLE_REG_OFFSET, 4);
+
+    reg_val = ioread32(addr);
+	pr_info("Reading SGPIO in SGPIO_ENABLE_REG: 0x%x\n", reg_val);
+    reg_val |= BIT(SGPIO_ENABLE_BIT);
+    pr_info("Enabling SGPIO in SGPIO_ENABLE_REG: 0x%x\n", reg_val);
+    iowrite32(reg_val, addr);
+    iounmap(addr);
+}
+
+static void airoha_sgpio_enable_rclk(struct airoha_sgpio *gpio)
+{
+    uint32_t reg_val;
+    void __iomem *addr = ioremap(SGPIO_ENABLE_REG_OFFSET, 4);
+    reg_val = ioread32(addr);
+	pr_info("Reading RCLK in SGPIO_ENABLE_REG: 0x%x\n", reg_val);
+    reg_val |= BIT(SGPIO_RCLK_ENABLE_BIT);
+    pr_info("Enabling RCLK in SGPIO_ENABLE_REG: 0x%x\n", reg_val);
+    iowrite32(reg_val, addr);
+    iounmap(addr);
+}
+
+static void airoha_sgpio_set_clk_div(struct airoha_sgpio *gpio, uint32_t clk_div)
+{
+    uint32_t reg_val;
+    void __iomem *addr = sgpio_reg(gpio, SGPIOCLK_OFFSET);
+
+    reg_val = ioread32(addr);
+	pr_info("Reading clock divisor in SGPIOCLK: 0x%x\n", reg_val);
+    reg_val &= ~GENMASK(1, 0); // Clear clock divisor bits
+    reg_val |= clk_div;
+
+    pr_info("Setting clock divisor in SGPIOCLK: 0x%x\n", reg_val);
+    iowrite32(reg_val, addr);
+}
+
+static void airoha_sgpio_set_clk_delay(struct airoha_sgpio *gpio, uint32_t clk_delay)
+{
+    uint32_t reg_val;
+    void __iomem *addr = sgpio_reg(gpio, SGPIOCLDLY_OFFSET);
+
+    reg_val = ioread32(addr);
+	pr_info("Reading clock delay in SGPIOCLDLY: 0x%x\n", reg_val);
+    reg_val &= ~GENMASK(3, 0); // Clear clock delay bits
+    reg_val |= clk_delay;
+
+    pr_info("Setting clock delay in SGPIOCLDLY: 0x%x\n", reg_val);
+    iowrite32(reg_val, addr);
+}
+
+static int airoha_sgpio_get(struct gpio_chip *gc, unsigned int offset)
+{
+    struct airoha_sgpio *gpio = gpiochip_get_data(gc);
+    uint32_t reg_val;
+    void __iomem *addr = sgpio_reg(gpio, SGPIODATA_OFFSET);
+
+    reg_val = ioread32(addr);
+    //pr_info("Reading SGPIODATA: 0x%x\n", reg_val);
+    return !!(reg_val & BIT(offset));
+}
+
+static void airoha_sgpio_set(struct gpio_chip *gc, unsigned int offset, int val)
+{
+    struct airoha_sgpio *gpio = gpiochip_get_data(gc);
+    uint32_t reg_val;
+    void __iomem *addr = sgpio_reg(gpio, SGPIODATA_OFFSET);
+    spin_lock(&gpio->lock);
+    reg_val = ioread32(addr);
+    if (val)
+        reg_val |= BIT(offset);
+    else
+        reg_val &= ~BIT(offset);
+
+    //pr_info("Setting SGPIODATA: 0x%x\n", reg_val);
+    airoha_sgpio_write_data(gpio, reg_val);
+    spin_unlock(&gpio->lock);
+}
+
+static int airoha_sgpio_dir_in(struct gpio_chip *gc, unsigned int offset)
+{
+    return 0; // SGPIO pins are always output
+}
+
+static int airoha_sgpio_dir_out(struct gpio_chip *gc, unsigned int offset, int val)
+{
+    airoha_sgpio_set(gc, offset, val);
+    return 0;
+}
+
+static int airoha_sgpio_get_direction(struct gpio_chip *gc, unsigned int offset)
+{
+    return GPIOF_DIR_OUT; // SGPIO pins are always output
+}
+
+static int airoha_sgpio_probe(struct platform_device *pdev)
+{
+    struct airoha_sgpio *gpio;
+    struct device *dev = &pdev->dev;
+    int rc;
+    uint32_t mode, clk_div, clk_delay;
+    int gpio_base = -1;
+
+    gpio = devm_kzalloc(dev, sizeof(*gpio), GFP_KERNEL);
+    if (!gpio)
+        return -ENOMEM;
+
+    gpio->base = devm_platform_ioremap_resource(pdev, 0);
+    if (IS_ERR(gpio->base))
+        return PTR_ERR(gpio->base);
+
+    if (device_property_read_u32(dev, "gpio_base", &gpio_base)) {
+        pr_err("gpio_arioha probe - gpio_base could not be read from dts.\n");
+    } else {
+        gpio->chip.base = gpio_base;
+    }
+
+    rc = of_property_read_u32(dev->of_node, "mode", &mode);
+    if (rc < 0) {
+        pr_err("Could not read mode property\n");
+        return -EINVAL;
+    }
+
+    rc = of_property_read_u32(dev->of_node, "clk-div", &clk_div);
+    if (rc < 0) {
+        pr_err("Could not read clk-div property\n");
+        return -EINVAL;
+    }
+
+    rc = of_property_read_u32(dev->of_node, "clk-delay", &clk_delay);
+    if (rc < 0) {
+        pr_err("Could not read clk-delay property\n");
+        return -EINVAL;
+    }
+    gpio->mode = mode;
+    gpio->clk_div = clk_div;
+    gpio->clk_delay = clk_delay;
+    spin_lock_init(&gpio->lock);
+    gpio->chip.parent = dev;
+    gpio->chip.ngpio = AIROHA_SGPIO_MAX;
+    gpio->chip.direction_input = airoha_sgpio_dir_in;
+    gpio->chip.direction_output = airoha_sgpio_dir_out;
+    gpio->chip.get_direction = airoha_sgpio_get_direction;
+    gpio->chip.get = airoha_sgpio_get;
+    gpio->chip.set = airoha_sgpio_set;
+    gpio->chip.label = dev_name(dev);
+
+    pr_info("Enabling SGPIO\n");
+    airoha_sgpio_enable(gpio);
+    pr_info("Setting SGPIO mode\n");
+    airoha_sgpio_set_mode(gpio, mode);
+    pr_info("Setting SGPIO clock divisor\n");
+    airoha_sgpio_set_clk_div(gpio, clk_div);
+
+    pr_info("Setting SGPIO clock delay\n");
+    airoha_sgpio_set_clk_delay(gpio, clk_delay);
+    if (mode == 1) { // 74595 mode
+        pr_info("Enabling RCLK for 74595 mode\n");
+        airoha_sgpio_enable_rclk(gpio);
+    }
+
+    rc = devm_gpiochip_add_data(dev, &gpio->chip, gpio);
+    if (rc < 0)
+        return rc;
+	
+    return 0;
+}
+
+static const struct of_device_id airoha_sgpio_of_table[] = {
+    { .compatible = "airoha,airoha-sgpio" },
+    {}
+};
+MODULE_DEVICE_TABLE(of, airoha_sgpio_of_table);
+
+static struct platform_driver airoha_sgpio_driver = {
+    .driver = {
+        .name = "airoha-sgpio",
+        .of_match_table = airoha_sgpio_of_table,
+    },
+    .probe = airoha_sgpio_probe,
+};
+
+module_platform_driver(airoha_sgpio_driver);
+
+MODULE_LICENSE("GPL v2");
+MODULE_AUTHOR("Neha Rani <neha.rani@airoha.com");
+MODULE_DESCRIPTION("Airoha SGPIO Driver");
