-static int8_t select_gen_wave(struct pwm_airoha_chip *pc, u8 gpio_pin, uint32_t period, uint8_t low)
-{
-	int wave_num = -1, i, mapped_gpio;
-	int index = 0;
-
-	mapped_gpio = gpio_map_pwmgpio(gpio_pin);
