+/* gpio_map_pwmgpio only for RSP_mode, flash_enable, mapping_gen_wave
+ * you might get in trouble if you use for other function
+ */
+ 
+static int8_t gpio_map_pwmgpio(u8 gpio_pin)
+{
+	int8_t ret;
+	switch (gpio_pin){
+		case 0 ... 15 :
+			ret = gpio_pin;
+			break;
+		case 16 ... 23 :
+			ret = (gpio_pin & 15) + 8;
+			break;
+		case 24 ... 31 :
+			ret = (gpio_pin & 15);
+			break;
+		case 36 ... 43 :
+			ret = gpio_pin - 28;
+			break;
+		case 44 ... 51 :
+			ret = gpio_pin - 36;
+			break;
+		default :
