+static void gpio_reg_config(struct pwm_airoha_chip *pc, 
+	u32 (*get_func_p)(u8, struct pwm_airoha_chip *), 
+	void (*set_func_p)(u8, u32, struct pwm_airoha_chip *), 
+	u16 data, u8 num_per_reg)
+{
+	uint32_t value_tmp = 0;
+	uint16_t bitMask = 0;
+	uint8_t idx = 0;
+
+	if(get_func_p == &gpiopwm_get_gpio_flash_map_cfg
+		|| get_func_p == &gpiopwm_get_gpio_rsp_mode_cfg
+		|| get_func_p == &gpiopwm_get_gpio_flash_mode_cfg
+		|| get_func_p == &gpiopwm_get_sgpio_flash_map_cfg
+	){
+		if (is_sgpio_pin(pc->num)){
+			idx = pc->num - SGPIO_BASE;
+		}
+		else
+		{
+			idx = gpio_map_pwmgpio(pc->num);
+		}
+	}else{
+		idx = pc->waveGenNum;
+	}
+
+	switch(num_per_reg){
+		case 2:
+			bitMask = 0xffff;
+			break;
+		case 4:
+			bitMask = 0xff;
+			break;
+		case 8:
+			bitMask = 0xf;
+			break;
+		case 32:
+			bitMask = 0x1;
+			break;
+		default:
+			printk("[pwm]Warning:no action for num_per_reg %d\n", num_per_reg);
+			break;
+	}
+	if(get_func_p == &gpiopwm_get_gpio_flash_map_cfg || get_func_p == &gpiopwm_get_sgpio_flash_map_cfg)
+	{
+		bitMask = 7;
+	}
+	value_tmp = (*get_func_p)(idx, pc);
+	value_tmp = (value_tmp & (~(bitMask << ((BANK_SIZE/num_per_reg)*(idx % num_per_reg)))));
+	(*set_func_p)(idx, value_tmp | (data << ((BANK_SIZE/num_per_reg)*(idx % num_per_reg))), pc);
+}
