@@ -29,3 +29,31 @@ stop_service() {
 	echo "Stop 3rdpartyagent..."
 	return 0
 }
+
+send_signal_to_3rdpartyagent()
+{
+    local sig="$1"
+    local pid
+
+    pid=$(pidof 3rdpartyagent)
+
+    if [ -n "$pid" ]; then
+        kill -"$sig" $pid
+    fi
+}
+
+reload_service() {
+    local reason="$1"
+
+    case "$reason" in
+        pppoe_username)
+            send_signal_to_3rdpartyagent SIGUSR2 # update pppoe_username
+            ;;
+        config)
+            send_signal_to_3rdpartyagent SIGUSR1 # reload config
+            ;;
+        *)
+            send_signal_to_3rdpartyagent SIGUSR1 # reload config
+            ;;
+    esac
+}
